<?php
require_once __DIR__.'/m0/bootstrap.php';
foreach(array('Repository','Answers','AnalyticalExport','PartialProgress','EngineMapper') as $class)require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/'.$class.'.php';
use EIPSI\AssessmentEditor\Definition as D;
use EIPSI\AssessmentEditor\Repository as R;
use EIPSI\AssessmentEditor\Answers as A;
use EIPSI\AssessmentEditor\AnalyticalExport as X;
use EIPSI\AssessmentEditor\PartialProgress as P;
use EIPSI\AssessmentEditor\EngineMapper as M;
$tests=0;$failures=0;$owned=array();
function fn_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function fn_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function fn_reject($fn){try{$fn();}catch(Throwable $e){return;}throw new RuntimeException('Expected rejection');}
function fn_fixture(){return json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);}
function fn_one($type){$d=fn_fixture();$d['elements']=array_values(array_filter($d['elements'],static function($e)use($type){return $e['type']===$type;}));return D::validate($d);}
wp_set_current_user(1);
try{
fn_test('JS maximal functional fixture canonical and idempotent in PHP',function(){$d=fn_fixture();fn_assert(D::json(D::validate($d))===D::json($d));fn_assert(D::json(D::validate(D::validate($d)))===D::json($d));});
fn_test('historical fixtures load with default flow and numeric Likert meaning preserved',function(){foreach(array('fixture','parity-fixture','authoring-fixture','corrections-fixture') as $f){$d=D::validate(json_decode(file_get_contents(__DIR__.'/assessment-editor/'.$f.'.json'),true));fn_assert(isset($d['flow']['pages'][0]));foreach($d['elements'] as $e)if($e['type']==='likert')foreach($e['options'] as $i=>$o)fn_assert($o['value']===$e['properties']['min']+$i);}});
fn_test('arbitrary numeric Likert values and null label fallback are authoritative',function(){$d=fn_one('likert');$e=$d['elements'][0];fn_assert(A::value($e,$e['options'][2]['id'])===7);$e['options'][1]['value']=null;fn_assert(A::value($e,$e['options'][1]['id'])==='A veces');});
fn_test('scale values reject strings objects infinity booleans and arrays',function(){foreach(array('7',array('value'=>7),INF,true,array()) as $v){$d=fn_one('likert');$d['elements'][0]['options'][0]['value']=$v;fn_reject(function()use($d){D::validate($d);});}});
fn_test('Matrix shares independent column values without row aggregate',function(){$d=fn_one('matrix');$e=$d['elements'][0];$answers=array();foreach($e['properties']['matrix_rows'] as $r)$answers[$r['response_key']]=$e['options'][2]['id'];$rows=X::rows($d,$answers);fn_assert(count($rows)===2);fn_assert(array_column($rows,'variable_name')===array('phq_1','phq_2'));fn_assert(array_column($rows,'value')===array(7,7));});
fn_test('Engine rejects arbitrary and label fallback Likert instead of remapping',function(){fn_reject(function(){M::map(fn_one('likert'));});$d=fn_one('likert');$d['elements'][0]['options'][0]['value']=null;fn_reject(function()use($d){M::map($d);});});
fn_test('consecutive integer Likert still maps without scientific contract changes',function(){$d=fn_one('likert');foreach($d['elements'][0]['options'] as $i=>&$o)$o['value']=$d['elements'][0]['properties']['min']+$i;unset($o);$d['elements'][0]['options'][0]['value']=(float)$d['elements'][0]['options'][0]['value'];fn_assert(M::map($d)->toArray()['state']==='DRAFT');});
fn_test('page IDs derive from stable boundaries and titles survive order changes',function(){$d=fn_fixture();$first=$d['flow']['pages'][1];$d['elements']=array_reverse($d['elements']);$n=D::validate($d);$found=array_column($n['flow']['pages'],null,'id');fn_assert($found[$first['id']]['title']===$first['title']);});
fn_test('flow policy enums booleans and extra settings fail closed',function(){foreach(array(array('progress','bad'),array('allow_back','false'),array('metadata_profile','vas-detailed')) as $bad){$d=fn_fixture();$d['flow'][$bad[0]]=$bad[1];fn_reject(function()use($d){D::validate($d);});}$d=fn_fixture();$d['flow']['session_days']=7;fn_reject(function()use($d){D::validate($d);});});
fn_test('page completion and instruction rich HTML sanitized without unsafe URL',function(){$d=fn_fixture();$d['flow']['pages'][0]['description_html']='<b>Safe</b><script>bad()</script>';$d['flow']['completion']['message_html']='<a href="javascript:bad()">Bad</a>';$n=D::validate($d);fn_assert(strpos($n['flow']['pages'][0]['description_html'],'<script')===false);fn_assert(strpos($n['flow']['completion']['message_html'],'javascript:')===false);$d['flow']['completion']['image_url']='javascript:bad()';fn_reject(function()use($d){D::validate($d);});});
fn_test('recovery units share one bounded window including explicit thirty-day months',function(){foreach(array('minutes'=>60,'hours'=>3600,'days'=>86400,'weeks'=>604800,'months'=>2592000) as $unit=>$seconds){$d=fn_fixture();$d['flow']['save_continue']['window']=array('value'=>1,'unit'=>$unit);$d=D::validate($d);fn_assert(\EIPSI\AssessmentEditor\Flow::retention($d)===$seconds);}});
fn_test('invalid recovery values units and unbounded retention rejected',function(){foreach(array(array(0,'days'),array(1.5,'days'),array(1,'years'),array(100000,'months')) as $bad){$d=fn_fixture();$d['flow']['save_continue']['window']=array('value'=>$bad[0],'unit'=>$bad[1]);fn_reject(function()use($d){D::validate($d);});}});
fn_test('Save Continue OFF creates no partial and removes prior native owner state',function(){$d=fn_one('text');P::save($d,array(),array(),0,array(),time());$d['flow']['save_continue']['enabled']=false;fn_assert(P::save($d,array(),array(),0,array())===null);fn_assert(P::resume($d)===null);});
fn_test('partial save resume preserves answers page metadata and original retention',function(){$d=fn_fixture();$now=time();$key=$d['elements'][0]['response_key'];$metadata=array('started_at'=>$now-30,'events'=>array(array('kind'=>'presented')));$first=P::save($d,array($key=>'final text'),array(),1,$metadata,$now);$again=P::save($d,array($key=>'final text'),array(),1,$metadata,$now+5);fn_assert($again['created_at']===$first['created_at']&&$again['expires_at']===$first['expires_at']);$r=P::resume($d,$now+10);fn_assert($r['page']===1&&$r['metadata']===$metadata&&$r['answers'][$key]==='final text');P::clear($d);});
fn_test('expired partial cannot resume and is physically removed by owner cleanup',function(){global $wpdb;$d=fn_one('text');$r=P::save($d,array(),array(),0,array(),time());fn_assert(P::resume($d,$r['expires_at'])===null);$r=P::save($d,array(),array(),0,array(),time());fn_assert(P::cleanup($r['expires_at']+1)>=1);fn_assert(P::resume($d)===null);});
fn_test('definition change invalidates recovery and completion clears partial',function(){$d=fn_one('text');P::save($d,array(),array(),0,array());$d['title']='Changed';fn_assert(P::resume($d)===null);P::save($d,array(),array(),0,array());P::clear($d);fn_assert(P::resume($d)===null);});
fn_test('partial rejects invalid unknown answers page and excessive metadata',function(){$d=fn_one('text');fn_reject(function()use($d){P::save($d,array('R_UNKNOWN'=>'bad'),array(),0,array());});fn_reject(function()use($d){P::save($d,array(),array(),99,array());});fn_reject(function()use($d){P::save($d,array(),array(),0,array('blob'=>str_repeat('x',600000)));});});
fn_test('native partial owner remains capability-protected',function(){$d=fn_one('text');wp_set_current_user(0);try{fn_reject(function()use($d){P::resume($d);});fn_reject(function()use($d){P::save($d,array(),array(),0,array());});}finally{wp_set_current_user(1);}});
fn_test('long technical identities yield bounded stable pages and derived collisions reject',function(){$d=fn_fixture();$d['id']='A'.str_repeat('x',99);$d['flow']['pages']=array();$n=D::validate($d);fn_assert(strlen($n['flow']['pages'][0]['id'])<=100);$id=$n['flow']['pages'][0]['id'];$n['id']='AE_COPY';fn_assert(D::validate($n)['flow']['pages'][0]['id']===$id);$d=fn_fixture();$d['flow']['pages'][0]['id']=$d['flow']['pages'][1]['id'];array_splice($d['flow']['pages'],1,1);fn_reject(function()use($d){D::validate($d);});});
fn_test('tidy analytical export exposes variable and complete provenance',function(){$d=fn_one('text');$e=$d['elements'][0];$rows=X::rows($d,array($e['response_key']=>'answer'),array(),array('study_version_id'=>'V_TEST','timepoint'=>'W4','block_execution_id'=>'B_TEST'));$r=$rows[0];fn_assert($r['variable_name']==='ansiedad'&&$r['item_id']===$e['id']&&$r['response_key']===$e['response_key']&&$r['study_version_id']==='V_TEST'&&$r['timepoint']==='W4');fn_assert(strlen($r['definition_hash'])===64);});
fn_test('independent Assessments may export same variable with separate timepoints',function(){$a=fn_one('text');$b=$a;$b['id']='AE_TIMEPOINT_TWO';$r1=X::rows($a,array(),array(),array('timepoint'=>'baseline'));$r2=X::rows($b,array(),array(),array('timepoint'=>'W4'));fn_assert($r1[0]['variable_name']===$r2[0]['variable_name']&&$r1[0]['assessment_id']!==$r2[0]['assessment_id']);});
fn_test('CSV escapes formula strings while preserving numeric negative values',function(){$csv=X::csv(array(array('value'=>'=CMD()'),array('value'=>-7)));fn_assert(strpos($csv,"'=CMD()")!==false&&strpos($csv,'-7')!==false);});
fn_test('analytical export rejects invalid responses and preserves Multiple arrays',function(){$d=fn_one('multiple_choice');$e=$d['elements'][0];$ids=array($e['options'][0]['id'],$e['options'][1]['id']);fn_assert(X::rows($d,array($e['response_key']=>$ids))[0]['value']===$ids);fn_reject(function()use($d){X::rows($d,array('unknown'=>'x'));});});
fn_test('removed one-way import action has no backend owner',function(){fn_assert(!file_exists(EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/GutenbergImporter.php'));fn_assert(strpos(file_get_contents(EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/Admin.php'),"case 'import':")===false);});
fn_test('removed import UI has no source prompt or action',function(){$s=file_get_contents(EIPSI_FORMS_PLUGIN_DIR.'src/admin/assessment-editor/app.js');fn_assert(strpos($s,'Importar Gutenberg')===false&&strpos($s,'post_id: source')===false);});
fn_test('removed import provenance cannot enter the native definition',function(){$d=fn_fixture();$d['import_source']=array();fn_reject(function()use($d){D::validate($d);});});
