fn_test('navigation next custom copy survives backend roundtrip',function(){$d=fn_fixture();$d['flow']['navigation_labels']['next']='Personalizado';fn_assert(D::validate($d)['flow']['navigation_labels']['next']==='Personalizado');});
fn_test('navigation finish custom copy survives backend roundtrip',function(){$d=fn_fixture();$d['flow']['navigation_labels']['finish']='Personalizado';fn_assert(D::validate($d)['flow']['navigation_labels']['finish']==='Personalizado');});
fn_test('historical flow receives empty navigation labels without changing page identities',function(){$d=fn_fixture();unset($d['flow']['navigation_labels']);$ids=array_column($d['flow']['pages'],'id');$n=D::validate($d);fn_assert(array_column($n['flow']['pages'],'id')===$ids&&$n['flow']['navigation_labels']===array('back'=>'','next'=>'','finish'=>''));});
fn_test('navigation copy rejects extra labels and non-string values',function(){$d=fn_fixture();$d['flow']['navigation_labels']['back']=array();fn_reject(function()use($d){D::validate($d);});$d=fn_fixture();$d['flow']['navigation_labels']['redirect']='https://example.test';fn_reject(function()use($d){D::validate($d);});});
