fn_test('page description editing preserves response identities',function(){$d=fn_fixture();$keys=array_column($d['elements'],'response_key');$d['flow']['pages'][0]['description_html']='<h2>Instrucciones</h2>';fn_assert(array_column(D::validate($d)['elements'],'response_key')===$keys);});
