fn_test('legacy rendering infrastructure remains present after importer retirement',function(){fn_assert(file_exists(EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/content/TemplateAdapter.php'));fn_assert(file_exists(EIPSI_FORMS_PLUGIN_DIR.'assets/js/eipsi-forms.js'));});
fn_test('current local demo installer has no Gutenberg source creation',function(){$s=file_get_contents(__DIR__.'/assessment-editor/install-functional-review.php');fn_assert(strpos($s,'wp_insert_post')===false&&strpos($s,'source_post')===false);});
fn_test('settings and rich content survive native save load without scientific writes',function()use(&$owned){$d=fn_fixture();$d['id']='AE_'.bin2hex(random_bytes(12));$d=D::validate($d);$owned[]=$d['id'];R::save($d,0);fn_assert(D::json(R::load($d['id'])['definition'])===D::json($d));});
