fn_test('native design roundtrips colors dimensions presets and navigation policy',function(){
    $d=fn_fixture();$d['flow']['design']=array('preset'=>'Serene Teal','primary'=>'#0e7490','background'=>'#ffffff','text'=>'#0c4a6e','button_text'=>'#ffffff','font'=>'serif','font_size'=>18,'width'=>900,'padding'=>44,'gap'=>28,'radius'=>16,'shadow'=>true,'navigation_alignment'=>'center');
    $n=D::validate($d);fn_assert($n['flow']['design']===$d['flow']['design']);fn_assert(array_column($n['elements'],'response_key')===array_column($d['elements'],'response_key'));
