fn_test('native design rejects CSS injection invalid enum and dimensions',function(){
    $valid=array('preset'=>'Clinical Blue','primary'=>'#3b6caa','background'=>'#ffffff','text'=>'#2c3e50','button_text'=>'#ffffff','font'=>'system','font_size'=>16,'width'=>800,'padding'=>40,'gap'=>24,'radius'=>12,'shadow'=>true,'navigation_alignment'=>'edges');
    foreach(array('primary'=>'red; background:url(https://example.test)','font'=>'url(test)','width'=>999999,'padding'=>-1,'font_size'=>16.5,'navigation_alignment'=>'overlay','shadow'=>'true','preset'=>'Unknown','extra'=>'bad') as $key=>$value){$d=fn_fixture();$d['flow']['design']=$valid;$d['flow']['design'][$key]=$value;fn_reject(function()use($d){D::validate($d);});}
});
fn_test('single rich completion preserves headings image and scientific page identities',function(){
    $d=fn_fixture();$ids=array_column($d['flow']['pages'],'id');$d['flow']['completion']['title']='';$d['flow']['completion']['image_url']='';$d['flow']['completion']['message_html']='<h2>Listo</h2><p>Gracias</p><img src="/wp-content/uploads/test.png" onerror="alert(1)"><script>bad</script>';
    $n=D::validate($d);fn_assert(array_column($n['flow']['pages'],'id')===$ids);$html=$n['flow']['completion']['message_html'];fn_assert(strpos($html,'<h2>Listo</h2>')!==false&&strpos($html,'test.png')!==false&&strpos($html,'onerror')===false&&strpos($html,'<script')===false);
});
fn_test('Matrix individual optional override persists and backend requires only selected items',function()use(&$owned){
    $d=fn_one('matrix');$d['id']='AE_'.bin2hex(random_bytes(12));$e=&$d['elements'][0];$e['properties']['required']=false;foreach($e['properties']['matrix_rows'] as &$row)$row['required']=true;unset($row);$e['properties']['matrix_rows'][0]['required']=false;
    $d=D::validate($d);$owned[]=$d['id'];R::save($d,0);$n=R::load($d['id'])['definition'];$rows=$n['elements'][0]['properties']['matrix_rows'];$errors=A::errors($n,array());fn_assert(count($errors)===count($rows)-1);fn_assert(!in_array($rows[0]['id'],array_column($errors,'id'),true));$answers=array();foreach(array_slice($rows,1) as $row)$answers[$row['response_key']]=$n['elements'][0]['options'][0]['id'];fn_assert(A::errors($n,$answers)===array());
});
fn_test('optional assessment title visibility roundtrips and rejects nonboolean values',function()use(&$owned){
    $d=fn_fixture();fn_assert(!array_key_exists('show_title',D::validate($d)['flow']));$d['id']='AE_'.bin2hex(random_bytes(12));$d['flow']['show_title']=false;$owned[]=$d['id'];R::save($d,0);fn_assert(R::load($d['id'])['definition']['flow']['show_title']===false);
    $d['flow']['show_title']=true;fn_assert(D::validate($d)['flow']['show_title']===true);foreach(array(null,'false',0,array()) as $bad){$d['flow']['show_title']=$bad;fn_reject(function()use($d){D::validate($d);});}
});
}finally{wp_set_current_user(1);P::clear(fn_fixture());P::clear(fn_one('text'));foreach($owned as $id)delete_option(R::PREFIX.$id);}
